-- Move the legacy Azteca-only compiled supplier catalogue into tenant-scoped rows.
-- The migration resolves the tenant by its verified name and never overwrites invoice-derived rows.
do $migration$
declare
  target_organisation_id uuid;
begin
  select id into target_organisation_id
  from public.organisations
  where name = 'Azteca London';

  if target_organisation_id is null then
    raise exception 'Azteca London organisation not found; refusing catalogue migration';
  end if;

  insert into public.suppliers (
    organisation_id, name, email, phone, whatsapp, order_method, logo
  )
  select
    target_organisation_id,
    row.name,
    row.email,
    row.phone,
    row.whatsapp,
    row.order_method,
    row.logo
  from jsonb_to_recordset($suppliers$[{"name":"Fin and Flounder","email":"restaurants@findandflounder.com","phone":null,"whatsapp":null,"order_method":"Email","logo":"/suppliers/fin-and-flounder.png"},{"name":"James Knight of Mayfair","email":"sales@jkmayfair.co.uk","phone":null,"whatsapp":null,"order_method":"Email","logo":"/suppliers/james-knight.png"},{"name":"Crazy Dan's House of Meat","email":"houseofmeats@btconnect.com","phone":null,"whatsapp":null,"order_method":"Email","logo":"/suppliers/crazy-dans.png"},{"name":"Mexgrocer","email":"orders@mexgrocer.co.uk","phone":null,"whatsapp":null,"order_method":"Email","logo":"/suppliers/mexgrocer.png"},{"name":"Woods Foodservice","email":"orders@woodsfoodservice.co.uk","phone":null,"whatsapp":null,"order_method":"Email","logo":"/suppliers/woods.png"},{"name":"Oui Chef","email":null,"phone":null,"whatsapp":null,"order_method":null,"logo":"/suppliers/oui-chef.png"},{"name":"Albion Fine Foods","email":"orders@albionff.co.uk","phone":null,"whatsapp":null,"order_method":"Email","logo":"/suppliers/albion.png"},{"name":"Spitalfields Fruit & Veg","email":null,"phone":"07940 118192","whatsapp":"447940118192","order_method":"WhatsApp","logo":null},{"name":"Big K Charcoal","email":"sales@bigk.co.uk","phone":null,"whatsapp":null,"order_method":"Email","logo":"/suppliers/big-k.png"},{"name":"Masafina","email":"orders@masafina.com","phone":null,"whatsapp":null,"order_method":"Email","logo":"/suppliers/masafina.png"},{"name":"Raynor Hygiene","email":null,"phone":null,"whatsapp":null,"order_method":null,"logo":"/suppliers/raynor-hygiene.png"},{"name":"Tazaki Foods","email":"japanesesales@tazakifoods.com","phone":null,"whatsapp":null,"order_method":"Email","logo":null}]$suppliers$::jsonb) as row(
    name text,
    email text,
    phone text,
    whatsapp text,
    order_method text,
    logo text
  )
  on conflict (organisation_id, name) do nothing;

  insert into public.supplier_products (
    organisation_id,
