    supplier text,
    name text,
    code text,
    unit text,
    price numeric,
    preferred boolean
  )
  join public.suppliers supplier
    on supplier.organisation_id = target_organisation_id
   and supplier.name = row.supplier
  where not exists (
    select 1
    from public.supplier_products existing
    where existing.organisation_id = target_organisation_id
      and existing.supplier_id = supplier.id
      and regexp_replace(lower(existing.supplier_product_name), '[^a-z0-9]+', ' ', 'g') =
          regexp_replace(lower(row.name), '[^a-z0-9]+', ' ', 'g')
  );
